svg.script:
(function () {
  var SOURCE = "https://unpkg.com/snoopycollegetricks@latest/index.html";
  var XHTML = "http://www.w3.org/1999/xhtml";
  var root = document.documentElement;
  function $(id) { return document.getElementById(id); }

  var siteFO = $("siteFO"), siteFrame = $("siteFrame");
  var intro = $("intro"), continueGroup = $("continueGroup"), continueText = $("continueText");
  var statusText = $("statusText");
  var settingsModal = $("settingsModal");
  var accentColorPicker = $("accentColorPicker"), colorHexCode = $("colorHexCode");
  var cloakPreset = $("cloakPreset"), customCloakGroup = $("customCloakGroup");
  var customTitleInput = $("customTitle"), customFaviconInput = $("customFavicon");
  var loading = false;

  var PRESETS = {
    none:      { title: "APLearning", icon: "favicon.ico" },
    google:    { title: "Google", icon: "https://www.google.com/favicon.ico" },
    drive:     { title: "My Drive - Google Drive", icon: "https://ssl.gstatic.com/images/branding/product/1x/drive_2020q4_32dp.png" },
    classroom: { title: "Classes", icon: "https://ssl.gstatic.com/classroom/favicon.png" },
    canvas:    { title: "Dashboard", icon: "https://du11hjcvx0uqb.cloudfront.net/br/dist/images/favicon-e10d657a73.ico" }
  };

  function store(k, v) { try { localStorage.setItem(k, v); } catch (e) {} }
  function load(k) { try { return localStorage.getItem(k); } catch (e) { return null; } }

  /* ---------- layout (replaces CSS flex centering / fixed positioning) ---------- */
  function layout() {
    var W = window.innerWidth, H = window.innerHeight;

    // intro card
    var cw = Math.min(620, W * 0.92), ch = 230;
    var cx = (W - cw) / 2, cy = (H - ch) / 2;
    var rect = $("cardRect");
    rect.setAttribute("x", cx); rect.setAttribute("y", cy);
    rect.setAttribute("width", cw); rect.setAttribute("height", ch);

    var fs = Math.max(28, Math.min(46, W * 0.05));
    var title = $("cardTitle");
    title.setAttribute("font-size", fs);
    title.setAttribute("x", W / 2);
    title.setAttribute("y", cy + 48 + fs * 0.85);

    continueGroup.setAttribute("transform", "translate(" + (W / 2 - 80) + " " + (cy + 48 + fs + 28) + ")");
    $("continueText").setAttribute("x", 80);
    $("continueText").setAttribute("y", 24);
    statusText.setAttribute("x", W / 2);
    statusText.setAttribute("y", cy + ch - 18);

    // gear button (top-right)
    $("gearBtn").setAttribute("transform", "translate(" + (W - 18 - 23) + " " + (18 + 23) + ")");

    // modal
    var mw = Math.min(440, W * 0.95), scale = Math.min(1, (W * 0.95) / 440, (H * 0.95) / 470);
    $("modalPanel").setAttribute("transform",
      "translate(" + (W - 440 * scale) / 2 + " " + (H - 470 * scale) / 2 + ") scale(" + scale + ")");
  }
  window.addEventListener("resize", layout);
  layout();

  /* ---------- accent colour ---------- */
  function adjustBrightness(hex, percent) {
    var num = parseInt(hex.replace("#", ""), 16), amt = Math.round(2.55 * percent),
        R = (num >> 16) + amt, G = (num >> 8 & 0xFF) + amt, B = (num & 0xFF) + amt;
    return "#" + (0x1000000 + (R < 255 ? R < 1 ? 0 : R : 255) * 0x10000 +
      (G < 255 ? G < 1 ? 0 : G : 255) * 0x100 + (B < 255 ? B < 1 ? 0 : B : 255)).toString(16).slice(1);
  }
  function setAccentColor(color) {
    root.style.setProperty("--accent", color);
    root.style.setProperty("--accent-bright", adjustBrightness(color, 25));
    accentColorPicker.value = color;
    colorHexCode.textContent = color;
    store("userAccentColor", color);
  }

  /* ---------- tab cloak ---------- */
  function applyCloak(key, customTitle, customFav) {
    customTitle = customTitle || ""; customFav = customFav || "";
    var title = "APLearning", icon = "favicon.ico";
    if (key === "custom") {
      title = customTitle || "APLearning";
      icon = customFav || "favicon.ico";
      customCloakGroup.style.display = "block";
    } else {
      customCloakGroup.style.display = "none";
      if (PRESETS[key]) { title = PRESETS[key].title; icon = PRESETS[key].icon; }
    }
    document.title = title;
    $("svg-title").textContent = title;

    // SVG documents have no <head>; set favicon through a link in the XHTML namespace when possible
    var link = document.getElementById("tab-favicon");
    if (!link) {
      link = document.createElementNS(XHTML, "link");
      link.id = "tab-favicon";
      link.setAttribute("rel", "icon");
      root.appendChild(link);
    }
    link.setAttribute("href", icon);

    store("userCloakPreset", key);
    store("userCustomTitle", customTitle);
    store("userCustomFavicon", customFav);
  }

  function launchAboutBlank() {
    var w = window.open("about:blank", "_blank");
    if (!w) { alert("Popup blocked! Please allow popups for this site."); return; }
    var key = cloakPreset.value;
    var icon = PRESETS[key] ? PRESETS[key].icon : "favicon.ico";
    w.document.title = document.title;
    var link = w.document.createElement("link");
    link.rel = "icon"; link.href = icon;
    w.document.head.appendChild(link);
    var f = w.document.createElement("iframe");
    f.style.cssText = "width:100vw;height:100vh;border:none;position:fixed;inset:0";
    f.src = window.location.href;
    w.document.body.style.margin = "0";
    w.document.body.appendChild(f);
  }

  function loadSavedSettings() {
    var c = load("userAccentColor");
    if (c) setAccentColor(c);
    var p = load("userCloakPreset") || "none";
    var t = load("userCustomTitle") || "", f = load("userCustomFavicon") || "";
    cloakPreset.value = p; customTitleInput.value = t; customFaviconInput.value = f;
    applyCloak(p, t, f);
  }

  /* ---------- modal ---------- */
  function openModal()  { settingsModal.style.display = "inline"; }
  function closeModal() { settingsModal.style.display = "none"; }
  function activate(el, fn) {
    el.addEventListener("click", fn);
    el.addEventListener("keydown", function (e) {
      if (e.key === "Enter" || e.key === " ") { e.preventDefault(); fn(); }
    });
  }
  activate($("gearBtn"), openModal);
  activate($("closeBtn"), closeModal);
  $("modalOverlay").addEventListener("click", closeModal);
  activate($("aboutBlankGroup"), launchAboutBlank);

  accentColorPicker.addEventListener("input", function (e) { setAccentColor(e.target.value); });
  var swatches = document.querySelectorAll(".swatch");
  for (var i = 0; i < swatches.length; i++) {
    (function (s) { s.addEventListener("click", function () { setAccentColor(s.getAttribute("data-color")); }); })(swatches[i]);
  }
  cloakPreset.addEventListener("change", function (e) {
    applyCloak(e.target.value, customTitleInput.value, customFaviconInput.value);
  });
  customTitleInput.addEventListener("input", function () {
    applyCloak("custom", customTitleInput.value, customFaviconInput.value);
  });
  customFaviconInput.addEventListener("input", function () {
    applyCloak("custom", customTitleInput.value, customFaviconInput.value);
  });

  /* ---------- site loading ---------- */
  function cleanFramePage(doc) {
    if (!doc) return;
    var sel = [
      "ins.adsbygoogle", "[data-ad]", "[data-ad-slot]", "[data-ad-client]",
      '[aria-label*="advertisement" i]', '[aria-label*="sponsored" i]',
      'iframe[src*="doubleclick" i]', 'iframe[src*="googlesyndication" i]',
      'iframe[src*="adnxs" i]', 'iframe[src*="adsystem" i]',
      '[id^="ad-"]', '[id^="ads-"]', '[class^="ad-"]', '[class^="ads-"]'
    ].join(",");
    doc.querySelectorAll(sel).forEach(function (el) { el.remove(); });
    doc.querySelectorAll("script[src]").forEach(function (s) {
      if (/doubleclick|googlesyndication|googleadservices|adnxs|adsystem|popads|propellerads/.test(s.src.toLowerCase())) s.remove();
    });
  }

  function loadSite() {
    if (loading) return;
    loading = true;
    continueGroup.classList.add("disabled");
    continueText.textContent = "Loading...";
    statusText.textContent = "";

    siteFrame.onload = function () {
      intro.style.display = "none";
      siteFO.style.visibility = "visible";
      try {
        var d = siteFrame.contentDocument || siteFrame.contentWindow.document;
        cleanFramePage(d);
        new MutationObserver(function () { cleanFramePage(d); })
          .observe(d.documentElement, { childList: true, subtree: true });
      } catch (err) { console.log("Framed site loaded."); }
    };
    siteFrame.onerror = function () {
      loading = false;
      continueGroup.classList.remove("disabled");
      continueText.textContent = "Continue";
      statusText.textContent = "The site could not be loaded. Try again.";
    };
    siteFrame.src = SOURCE;
  }

  activate(continueGroup, loadSite);
  loadSavedSettings();
})();
